mapper.select:
SELECT p.productId, p.productName, p.categoryId, c.categoryName, p.barcode, p.unit, p.spec, p.defaultPrice, p.alertMin, p.status FROM product p LEFT JOIN category c ON p.categoryId = c.categoryId
AND (p.productName LIKE CONCAT('%', #{keyword}, '%') OR p.barcode LIKE CONCAT('%', #{keyword}, '%'))
AND p.categoryId = #{categoryId}
AND p.status = #{status}
ORDER BY p.productId DESC
